<template>
	<div class="min-h-dvh flex items-center justify-center bg-ui-raised px-6 py-10 pb-24 sm:pb-32">
		<div class="w-full max-w-sm flex flex-col items-center">
			<img
				:src="logoUrl"
				alt="Juragan"
				class="w-24 h-24 sm:w-28 sm:h-28 object-contain mb-12 sm:mb-14"
			/>

			<!-- Memulihkan langkah terakhir setelah halaman ditutup/dibuka lagi -->
			<div
				v-if="memulihkan"
				class="w-full flex items-center justify-center gap-2 py-8 text-sm text-ui-ink-gray-600"
			>
				<svg
					class="animate-spin"
					xmlns="http://www.w3.org/2000/svg"
					width="16"
					height="16"
					viewBox="0 0 24 24"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
				>
					<path d="M21 12a9 9 0 1 1-6.219-8.56" />
				</svg>
				<span>Memuat permintaan Anda...</span>
			</div>

			<!-- Langkah 1: identitas pemohon -->
			<form
				v-else-if="step === 'identitas'"
				@submit.prevent="handleIdentitas"
				class="w-full flex flex-col space-y-4"
			>
				<input
					v-model="email"
					type="text"
					inputmode="email"
					autocomplete="username"
					placeholder="Email terdaftar"
					required
					class="w-full px-5 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading transition-shadow"
				/>

				<input
					v-model="fullName"
					type="text"
					autocomplete="name"
					placeholder="Nama lengkap"
					required
					class="w-full px-5 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading transition-shadow"
				/>

				<p class="text-xs text-ui-ink-gray-600 px-1 leading-relaxed">
					Email harus yang terdaftar di sistem. Nama lengkap tidak perlu sama persis —
					dipakai administrator untuk memastikan siapa yang menghubungi. Permintaan Anda
					diteruskan ke administrator untuk disetujui.
				</p>

				<button
					type="submit"
					:disabled="loading"
					class="w-full mt-2 py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-70 flex justify-center items-center"
				>
					<span v-if="loading">Memproses...</span>
					<span v-else>Lanjutkan</span>
				</button>
			</form>

			<!-- Langkah 2: menunggu persetujuan admin -->
			<div v-else-if="step === 'menunggu'" class="w-full flex flex-col space-y-4">
				<div
					class="px-5 py-4 bg-ui-surface-amber-50 border border-ui-line-amber-200 rounded-[1.25rem] text-ui-ink-amber-800 text-sm leading-relaxed"
				>
					<p class="font-semibold mb-1">Menunggu persetujuan administrator</p>
					<p>
						Permintaan untuk <span class="font-medium">{{ email }}</span> sudah
						dikirim. Hubungi administrator untuk mempercepat verifikasi.
					</p>
					<p class="mt-2">
						Begitu disetujui, form kata sandi baru muncul otomatis. Halaman ini boleh
						ditutup — permintaan Anda tetap tersimpan, dan Anda punya
						<span class="font-medium">1 jam</span> untuk mengatur kata sandi baru
						terhitung sejak disetujui.
					</p>
				</div>

				<div
					v-if="autoAktif"
					class="flex items-center justify-center gap-2 text-sm text-ui-ink-gray-600"
					aria-live="polite"
				>
					<svg
						class="animate-spin"
						xmlns="http://www.w3.org/2000/svg"
						width="16"
						height="16"
						viewBox="0 0 24 24"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					>
						<path d="M21 12a9 9 0 1 1-6.219-8.56" />
					</svg>
					<span>Memeriksa status otomatis...</span>
				</div>
			</div>

			<!-- Langkah 3: kata sandi baru -->
			<form
				v-else-if="step === 'sandi-baru'"
				@submit.prevent="handleSimpanSandi"
				class="w-full flex flex-col space-y-4"
			>
				<div
					class="px-5 py-3 bg-ui-surface-green-50 border border-ui-line-green-200 rounded-[1.25rem] text-ui-ink-green-800 text-sm"
				>
					Permintaan disetujui. Silakan atur kata sandi baru untuk
					<span class="font-medium">{{ email }}</span> dalam 1 jam ke depan.
				</div>

				<div class="relative">
					<input
						v-model="newPassword"
						:type="showPassword ? 'text' : 'password'"
						autocomplete="new-password"
						placeholder="Kata sandi baru"
						required
						class="w-full pl-5 pr-12 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading transition-shadow"
					/>
					<button
						type="button"
						@click="showPassword = !showPassword"
						:aria-label="
							showPassword ? 'Sembunyikan kata sandi' : 'Tampilkan kata sandi'
						"
						class="absolute inset-y-0 right-0 flex items-center pr-4 text-ui-heading hover:text-ui-ink focus:outline-none"
					>
						<svg
							v-if="showPassword"
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							stroke-width="1.75"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24" />
							<path
								d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"
							/>
							<path
								d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"
							/>
							<line x1="2" y1="2" x2="22" y2="22" />
						</svg>
						<svg
							v-else
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							stroke-width="1.75"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
							<circle cx="12" cy="12" r="3" />
						</svg>
					</button>
				</div>

				<input
					v-model="confirmPassword"
					:type="showPassword ? 'text' : 'password'"
					autocomplete="new-password"
					placeholder="Ulangi kata sandi baru"
					required
					class="w-full px-5 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading transition-shadow"
				/>

				<button
					type="submit"
					:disabled="loading"
					class="w-full mt-2 py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-70 flex justify-center items-center"
				>
					<span v-if="loading">Menyimpan...</span>
					<span v-else>Simpan Kata Sandi</span>
				</button>
			</form>

			<!-- Langkah 4: selesai -->
			<div v-else-if="step === 'selesai'" class="w-full flex flex-col space-y-4">
				<div
					class="px-5 py-4 bg-ui-surface-green-50 border border-ui-line-green-200 rounded-[1.25rem] text-ui-ink-green-800 text-sm leading-relaxed"
				>
					<p class="font-semibold mb-1">Kata sandi berhasil diubah</p>
					<p>Silakan masuk kembali menggunakan kata sandi baru Anda.</p>
					<p class="mt-2">
						Perubahan kata sandi berikutnya baru bisa diajukan setelah
						<span class="font-medium">12 jam</span>.
					</p>
				</div>

				<button
					type="button"
					@click="router.replace({ name: 'Login' })"
					class="w-full py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors"
				>
					Kembali ke Halaman Masuk
				</button>
			</div>

			<div
				v-if="errorMessage"
				role="alert"
				class="mt-4 w-full px-4 py-3 bg-ui-surface-red-50 border border-ui-line-red-200 rounded-[0.875rem] text-ui-ink-red-700 text-sm text-center"
			>
				{{ errorMessage }}
			</div>

			<button
				v-if="step !== 'selesai'"
				type="button"
				@click="kembaliKeLogin"
				class="mt-6 text-sm text-ui-heading underline underline-offset-4 hover:text-ui-ink focus:outline-none"
			>
				Kembali ke halaman masuk
			</button>
		</div>
	</div>
</template>

<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { call } from 'frappe-ui'
import { useAutoCheck } from '../composables/useAutoCheck'
import {
	readPortalState,
	removeLegacyStorageKey,
	removePortalState,
	STORAGE_TTL,
	writePortalState,
} from '../data/portalStorage'
// Di-import (bukan dari public/) supaya Vite yang mengurus URL-nya — benar di
// build web maupun APK, tanpa perlu ikut daftar salinan PWA di vite.config.
import logoUrl from '../assets/logo-juragan.png'

const router = useRouter()

const API = 'juragan.api.portal.password_reset'

// Identitas pemohon disimpan supaya halaman yang ditutup — atau APK yang
// dimatikan — kembali ke langkah yang sama tanpa mengetik ulang. Yang disimpan
// hanya email dan nama lengkap; tidak ada kata sandi atau token di sini.
// Dihapus begitu kata sandi berhasil diganti, ditolak, atau kedaluwarsa.
const STORAGE_KEY = 'juragan:lupa-kata-sandi'

// identitas -> menunggu -> sandi-baru -> selesai
const step = ref('identitas')
const email = ref('')
const fullName = ref('')
const newPassword = ref('')
const confirmPassword = ref('')
const showPassword = ref(false)
const loading = ref(false)
const errorMessage = ref('')
const memulihkan = ref(false)

function friendlyError(err) {
	const raw = err?.messages?.[0] || err?._error_message || err?.message || String(err || '')
	// Pesan validasi dari backend sudah berbahasa Indonesia, tampilkan apa adanya.
	const text = String(raw)
	if (/failed to fetch|network|load failed/i.test(text)) {
		return 'Tidak dapat terhubung ke server. Coba lagi.'
	}
	if (/too many requests|rate limit/i.test(text)) {
		return 'Terlalu banyak percobaan. Coba lagi satu jam berikutnya.'
	}
	// Backend membungkus pesan dalam HTML kalau berasal dari password policy.
	return (
		text
			.replace(/<[^>]*>/g, ' ')
			.replace(/\s+/g, ' ')
			.trim() || 'Terjadi kesalahan. Coba lagi.'
	)
}

// localStorage bisa dilarang (mode privat, WebView tertentu) — kegagalannya
// tidak boleh menjatuhkan alurnya, cuma kehilangan kenyamanan.
function simpanSesi() {
	writePortalState(
		'draft',
		'guest',
		'ForgotPassword',
		{ email: email.value.trim(), fullName: fullName.value.trim() },
		{ ttlMs: STORAGE_TTL.PASSWORD_RESET },
	)
}

function hapusSesi() {
	removePortalState('draft', 'guest', 'ForgotPassword')
	removeLegacyStorageKey(STORAGE_KEY)
}

function bacaSesi() {
	// Payload lama tidak memiliki timestamp dan sengaja tidak dimigrasikan.
	removeLegacyStorageKey(STORAGE_KEY)
	return readPortalState('draft', 'guest', 'ForgotPassword', {
		email: '',
		fullName: '',
	})
}

/** Arahkan ke langkah yang sesuai dengan status permintaan di server. */
function applyStatus(status, catatan, sisa) {
	if (status === 'approved') {
		// Belum selesai — kalau pemohon menutup halaman sekarang, dia harus
		// kembali ke form kata sandi, bukan ke awal.
		simpanSesi()
		step.value = 'sandi-baru'
		return true
	}
	if (status === 'pending') {
		simpanSesi()
		step.value = 'menunggu'
		return true
	}
	hapusSesi()
	if (status === 'rejected') {
		errorMessage.value = catatan
			? `Permintaan ditolak administrator: ${catatan}`
			: 'Permintaan ditolak administrator. Hubungi administrator untuk informasi lebih lanjut.'
		step.value = 'identitas'
		return true
	}
	if (status === 'cooldown') {
		errorMessage.value = sisa
			? `Kata sandi baru saja diubah. Perubahan berikutnya bisa diajukan dalam ${sisa} lagi.`
			: 'Kata sandi baru saja diubah. Tunggu beberapa saat sebelum mengajukan lagi.'
		step.value = 'identitas'
		return true
	}
	// 'none' dan 'expired' berarti belum/tidak lagi ada permintaan berjalan.
	return false
}

/** Tanya status ke server lalu pindah langkah. True kalau ada permintaan berjalan. */
async function cekStatus() {
	// Hanya email yang menentukan — nama lengkap tidak dipakai server untuk
	// mencari permintaan, jadi tidak perlu dikirim di sini.
	const cek = await call(`${API}.check_reset_status`, {
		email: email.value.trim(),
	})
	return applyStatus(cek?.status, cek?.catatan, cek?.sisa)
}

// --- pemeriksaan otomatis ---------------------------------------------------

const {
	aktif: autoAktif,
	start: mulaiAutoCek,
	stop: hentikanAutoCek,
} = useAutoCheck(cekStatus, {
	onError(error) {
		// Gangguan jaringan sesaat tidak perlu diteriakkan tiap 15 detik.
		// Tapi kalau kuota habis, polling harus berhenti daripada terus ditolak.
		const pesan = friendlyError(error)
		if (/terlalu banyak percobaan/i.test(pesan)) {
			hentikanAutoCek()
			errorMessage.value = pesan
		}
	},
})

// Polling hanya hidup selama pemohon berada di langkah "menunggu".
watch(step, (nilai) => {
	if (nilai === 'menunggu') mulaiAutoCek()
	else hentikanAutoCek()
})

// Pulihkan langkah terakhir kalau pemohon sempat menutup halaman. Statusnya
// selalu ditanyakan ulang ke server — yang tersimpan di perangkat cuma
// identitas, server tetap yang menentukan pemohon boleh sampai mana.
onMounted(async () => {
	const tersimpan = bacaSesi()
	if (!tersimpan?.email || !tersimpan?.fullName) return

	email.value = tersimpan.email
	fullName.value = tersimpan.fullName
	memulihkan.value = true
	try {
		await cekStatus()
	} catch (error) {
		// Server tidak terjangkau saat dibuka — jangan hapus sesinya, biarkan
		// pemohon menekan Lanjutkan sendiri dengan data yang sudah terisi.
	} finally {
		memulihkan.value = false
	}
})

/**
 * Satu tombol untuk dua keadaan: pemohon yang baru mengajukan, dan pemohon yang
 * kembali lagi setelah disetujui. Statusnya dicek dulu supaya pemohon yang
 * sudah disetujui langsung masuk ke form kata sandi, bukan membuat permintaan
 * duplikat.
 */
const handleIdentitas = async () => {
	errorMessage.value = ''
	loading.value = true
	try {
		if (await cekStatus()) return

		const hasil = await call(`${API}.request_password_reset`, {
			email: email.value.trim(),
			full_name: fullName.value.trim(),
		})
		applyStatus(hasil?.status)
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		loading.value = false
	}
}

const handleSimpanSandi = async () => {
	errorMessage.value = ''

	if (newPassword.value !== confirmPassword.value) {
		errorMessage.value = 'Konfirmasi kata sandi tidak sama.'
		return
	}

	loading.value = true
	try {
		await call(`${API}.submit_new_password`, {
			email: email.value.trim(),
			new_password: newPassword.value,
			confirm_password: confirmPassword.value,
		})
		newPassword.value = ''
		confirmPassword.value = ''
		hapusSesi()
		step.value = 'selesai'
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		loading.value = false
	}
}

const kembaliKeLogin = () => {
	router.replace({ name: 'Login' })
}
</script>
